import{_ as a,o as t,c as n,a2 as r}from"./chunks/framework.CqGS6Fr9.js";const p=JSON.parse('{"title":"Shared world and settlements","description":"","frontmatter":{"pageId":"players/world","contentRevision":2},"headers":[],"relativePath":"en/players/world.md","filePath":"en/players/world.md"}'),o={name:"en/players/world.md"};function l(i,e,s,d,c,h){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="shared-world-and-settlements" tabindex="-1">Shared world and settlements <a class="header-anchor" href="#shared-world-and-settlements" aria-label="Permalink to &quot;Shared world and settlements&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>All players use the server planet. Choose an unoccupied tile when creating a colony. Foreign settlements show their owner, presence, last-seen time, colony age and wealth band where available.</p><p>Caravans and transport pods offer actions at another settlement: transfer, raid, visit or live, depending on mode, host availability and server policy. Read the action label before confirming: a visit and a real raid are not interchangeable.</p><p>The guild overlay is optional and does not replace normal map markers.</p><h2 id="settlement" tabindex="-1">How do I settle and read another settlement? <a class="header-anchor" href="#settlement" aria-label="Permalink to &quot;How do I settle and read another settlement? {#settlement}&quot;">​</a></h2><p>Colony creation uses the server&#39;s existing planet. Find a free tile, inspect biome/terrain and settle. If another player claimed it concurrently, choose another tile; do not try saving a second settlement under the same account.</p><p>A green settlement indicator means its owner is online; gray means offline. Wealth bands 1–5 are not exact wallet balances. Select the object for owner, faction, last activity and colony age. Age is measured in game days; last activity is real time.</p><p>Select a caravan and right-click the settlement for actions. Read the complete label: transfer, raid, visit and live raid have different risks. Pods use their own arrival options. Alliance color does not replace those rules.</p><h2 id="archive" tabindex="-1">What happens after a long absence? <a class="header-anchor" href="#archive" aria-label="Permalink to &quot;What happens after a long absence? {#archive}&quot;">​</a></h2><p>The server may archive a young, low-wealth colony after a long absence, around two weeks by default with administrator-controlled conditions. This is not save deletion. Login restores it automatically if the tile remains free.</p><p>If occupied, do not overlay an old colony onto the new settlement. An administrator needs a free tile and controlled restoration. The “while you were away” letter summarizes server events; no letter can simply mean no events occurred.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>The default is one settlement per player. An offline marker does not mean the map keeps simulating. Peaceful mode disables some actions.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./visits">Visits and shops</a></li><li><a href="./raids-incidents">Raids and paid incidents</a></li><li><a href="./guild-influence">Guild influence</a></li></ul>',17)])])}const f=a(o,[["render",l]]);export{p as __pageData,f as default};
